) VALUES (
    'wengen-venue-guide',
    '{"en": "Wengen: The Longest Downhill in the World", "de": "Wengen: Die längste Abfahrt der Welt", "fr": "Wengen : La plus longue descente du monde", "it": "Wengen: La discesa più lunga del mondo", "es": "Wengen: El descenso más largo del mundo", "pt": "Wengen: A descida mais longa do mundo", "nl": "Wengen: De langste afdaling ter wereld", "ar": "وينغن: أطول انحدار في العالم", "ja": "ヴェンゲン：世界最長のダウンヒル", "zh": "Wengen: Shijie Zuichang de Huajiang", "ko": "벵겐: 세계에서 가장 긴 활강"}'::jsonb,
    '{"en": "The Lauberhorn downhill at Wengen is the longest race on the World Cup circuit. This car-free Swiss village offers a unique racing experience with stunning views of the Eiger.", "de": "Die Lauberhorn-Abfahrt in Wengen ist das längste Rennen im Weltcup-Zirkus.", "fr": "La descente du Lauberhorn à Wengen est la course la plus longue du circuit de la Coupe du monde.", "it": "La discesa del Lauberhorn a Wengen è la gara più lunga del circuito di Coppa del Mondo.", "es": "El descenso del Lauberhorn en Wengen es la carrera más larga del circuito de la Copa del Mundo.", "pt": "A descida do Lauberhorn em Wengen é a corrida mais longa do circuito da Copa do Mundo.", "nl": "De Lauberhorn afdaling in Wengen is de langste race op het Wereldbeker circuit.", "ar": "انحدار لاوبرهورن في وينغن هو أطول سباق في دورة كأس العالم", "ja": "ヴェンゲンのラウバーホルンダウンヒルは、ワールドカップサーキットで最も長いレースです。", "zh": "Wengen de Lauberhorn huajiang shi Shijie Bei saidao zhong zuichang de bisai.", "ko": "벵겐의 라우버호른 활강은 월드컵 서킷에서 가장 긴 레이스입니다."}'::jsonb,
    '{"en": "<p>Wengen''s Lauberhorn downhill is an endurance test unlike any other in World Cup <a href=\"/alpine-skiing-guide/\">alpine skiing</a>. At over 4.4 kilometers, it challenges athletes to maintain speed, focus, and technique for nearly two and a half minutes of racing.</p><h2>The Course</h2><p>The Lauberhorn starts high above Wengen and descends through varied terrain that tests every aspect of downhill racing. The famous Hundschopf jump, the tunnel section, and the gliding passages to the finish require completely different skills.</p><p>Athletes must pace themselves while still attacking - a unique challenge in speed skiing where races are typically much shorter.</p><h2>The Setting</h2><p>The race takes place with the iconic Eiger, Mönch, and Jungfrau peaks as a backdrop. This stunning Swiss scenery makes the Lauberhorn one of the most photogenic races on the circuit.</p><p>Champions like <a href=\"/marco-schwarz-profile/\">Marco Schwarz</a> and <a href=\"/vincent-kriechmayr-profile/\">Vincent Kriechmayr</a> have navigated this legendary course.</p><h2>Car-Free Village</h2><p>Wengen is a car-free village, accessible only by train. This creates a unique atmosphere where the mountains feel closer and the experience more traditional. The Wengernalp railway brings spectators and athletes to this alpine paradise.</p><h2>Racing Weekend</h2><p>The Lauberhorn weekend typically includes both the downhill and a slalom, testing athletes across the full spectrum of alpine skiing disciplines. The combination race draws huge crowds of Swiss skiing fans.</p><h2>History</h2><p>The Lauberhorn races have been held since 1930, making this one of the oldest events on the World Cup calendar. The course has evolved over the decades but maintains its character as a true test of alpine skiing skill.</p><h2>Getting There</h2><p>Wengen is reached by train from Interlaken. The journey by rail is part of the experience, offering spectacular views of the Bernese Oberland.</p>", "de": "<p>Die Lauberhorn-Abfahrt in Wengen ist ein Ausdauertest wie kein anderer im Weltcup-<a href=\"/alpine-skiing-guide/\">Ski Alpin</a>. Mit über 4,4 Kilometern fordert sie Athleten heraus, Geschwindigkeit, Fokus und Technik für fast zweieinhalb Minuten aufrechtzuerhalten.</p><h2>Die Strecke</h2><p>Das Lauberhorn startet hoch über Wengen und führt durch abwechslungsreiches Gelände. Der berühmte Hundschopf-Sprung, der Tunnelabschnitt und die Gleitpassagen zum Ziel erfordern völlig unterschiedliche Fähigkeiten.</p><h2>Die Kulisse</h2><p>Das Rennen findet vor der Kulisse der ikonischen Gipfel Eiger, Mönch und Jungfrau statt. Champions wie <a href=\"/marco-schwarz-profile/\">Marco Schwarz</a> haben diese Strecke bewältigt.</p><h2>Autofreies Dorf</h2><p>Wengen ist ein autofreies Dorf, nur per Zug erreichbar.</p>", "fr": "<p>La descente du Lauberhorn à Wengen est un test d''endurance sans pareil dans la Coupe du monde de <a href=\"/alpine-skiing-guide/\">ski alpin</a>. Avec plus de 4,4 kilomètres, elle met les athlètes au défi de maintenir vitesse, concentration et technique pendant près de deux minutes et demie.</p><h2>Le parcours</h2><p>Le Lauberhorn part haut au-dessus de Wengen et descend à travers un terrain varié.</p><h2>Le décor</h2><p>La course se déroule avec les sommets emblématiques de l''Eiger, du Mönch et de la Jungfrau en toile de fond. Des champions comme <a href=\"/marco-schwarz-profile/\">Marco Schwarz</a> ont navigué ce parcours légendaire.</p><h2>Village sans voiture</h2><p>Wengen est un village sans voiture, accessible uniquement en train.</p>", "it": "<p>La discesa del Lauberhorn a Wengen è un test di resistenza senza eguali nella Coppa del Mondo di <a href=\"/alpine-skiing-guide/\">sci alpino</a>. Con oltre 4,4 chilometri, sfida gli atleti a mantenere velocità, concentrazione e tecnica per quasi due minuti e mezzo.</p><h2>Il percorso</h2><p>Il Lauberhorn parte in alto sopra Wengen e scende attraverso un terreno vario.</p><h2>L''ambientazione</h2><p>La gara si svolge con i picchi iconici dell''Eiger, Mönch e Jungfrau come sfondo. Campioni come <a href=\"/marco-schwarz-profile/\">Marco Schwarz</a> hanno percorso questa pista leggendaria.</p>", "es": "<p>El descenso del Lauberhorn en Wengen es una prueba de resistencia sin igual en la Copa del Mundo de <a href=\"/alpine-skiing-guide/\">esquí alpino</a>. Con más de 4,4 kilómetros, desafía a los atletas a mantener velocidad, concentración y técnica durante casi dos minutos y medio.</p><h2>El recorrido</h2><p>El Lauberhorn comienza en lo alto sobre Wengen y desciende a través de terreno variado.</p>", "pt": "<p>A descida do Lauberhorn em Wengen é um teste de resistência sem igual na Copa do Mundo de <a href=\"/alpine-skiing-guide/\">esqui alpino</a>. Com mais de 4,4 quilômetros, desafia os atletas a manter velocidade, foco e técnica por quase dois minutos e meio.</p><h2>O percurso</h2><p>O Lauberhorn começa no alto acima de Wengen e desce através de terreno variado.</p>", "nl": "<p>De Lauberhorn afdaling in Wengen is een uithoudingstest zoals geen ander in de Wereldbeker <a href=\"/alpine-skiing-guide/\">alpine skiën</a>. Met meer dan 4,4 kilometer daagt het atleten uit om snelheid, focus en techniek bijna tweeëneenhalve minuut te behouden.</p><h2>Het parcours</h2><p>De Lauberhorn start hoog boven Wengen en daalt af door gevarieerd terrein.</p>", "ar": "<p>انحدار لاوبرهورن في وينغن هو اختبار تحمل لا مثيل له في كأس العالم <a href=\"/alpine-skiing-guide/\">للتزلج الألبي</a>. بأكثر من 4.4 كيلومتر، يتحدى الرياضيين للحفاظ على السرعة والتركيز والتقنية لما يقرب من دقيقتين ونصف.</p><h2>المسار</h2><p>يبدأ لاوبرهورن فوق وينغن وينحدر عبر تضاريس متنوعة.</p>", "ja": "<p>ヴェンゲンのラウバーホルンダウンヒルは、ワールドカップ<a href=\"/alpine-skiing-guide/\">アルペンスキー</a>で他に類を見ない持久力テストです。4.4キロメートル以上で、ほぼ2分半のレース中、スピード、集中力、テクニックを維持することを選手に要求します。</p><h2>コース</h2><p>ラウバーホルンはヴェンゲンの上方から始まり、様々な地形を下ります。</p>", "zh": "<p>Wengen de Lauberhorn huajiang shi Shijie Bei <a href=\"/alpine-skiing-guide/\">gaoshan huaxue</a> zhong duyiwuer de naili kaoyan. Chaoguo 4.4 gongli, ta tiaozhan yundongyuan zai jin liang fenban zhong baochi sudu, zhuanzhu he jishu.</p><h2>Saidao</h2><p>Lauberhorn cong Wengen shangfang kaishi, chuanguo butong dixing xiajiang.</p>", "ko": "<p>벵겐의 라우버호른 활강은 월드컵 <a href=\"/alpine-skiing-guide/\">알파인 스키</a>에서 비할 데 없는 지구력 테스트입니다. 4.4킬로미터 이상으로 거의 2분 30초 동안 속도, 집중력, 기술을 유지하도록 선수들에게 도전합니다.</p><h2>코스</h2><p>라우버호른은 벵겐 위에서 시작하여 다양한 지형을 통해 내려갑니다.</p>"}'::jsonb,
    'venue-guide',
    'AS',
    '{"en": "Wengen venue guide - Home of the Lauberhorn, the longest downhill race in World Cup alpine skiing at over 4.4 kilometers.", "de": "Wengen Venue Guide - Heimat des Lauberhorns, der längsten Abfahrt im Weltcup-Ski-Alpin.", "fr": "Guide du site de Wengen - Terre du Lauberhorn, la plus longue descente de la Coupe du monde de ski alpin.", "it": "Guida alla sede di Wengen - Casa del Lauberhorn, la discesa più lunga della Coppa del Mondo di sci alpino.", "es": "Guía del lugar de Wengen - Hogar del Lauberhorn, el descenso más largo de la Copa del Mundo de esquí alpino.", "pt": "Guia do local de Wengen - Lar do Lauberhorn, a descida mais longa da Copa do Mundo de esqui alpino.", "nl": "Wengen locatiegids - Thuis van de Lauberhorn, de langste afdaling in de Wereldbeker alpine skiën.", "ar": "دليل موقع وينغن - موطن لاوبرهورن، أطول انحدار في كأس العالم للتزلج الألبي", "ja": "ヴェンゲン会場ガイド - ラウバーホルンの本拠地、ワールドカップアルペンスキーで最長のダウンヒル", "zh": "Wengen changguan zhinan - Lauberhorn de jiayuan, Shijie Bei gaoshan huaxue zhong zuichang de huajiang", "ko": "벵겐 경기장 가이드 - 라우버호른의 본거지, 월드컵 알파인 스키에서 가장 긴 활강"}'::jsonb,
    'published',
    NOW(),
    'evergreen'
) ON CONFLICT (slug) DO UPDATE SET
    title = EXCLUDED.title,
    excerpt = EXCLUDED.excerpt,
    content = EXCLUDED.content,
